// (`action-pins.ts`) reports the same lines; this check does not rely on it.
const QUOTED_USES = /(?<![A-Za-z0-9_-])uses(?![A-Za-z0-9_-]).*["'\\]|["'\\].*(?<![A-Za-z0-9_-])uses(?![A-Za-z0-9_-])/;
